-- обязательные координаты и документ; одна строка на позицию Kafka.
SELECT count(*) AS n FROM (SELECT topic,kafka_partition,kafka_offset FROM {{target:oil_stg__event_log}} GROUP BY topic,kafka_partition,kafka_offset HAVING count(*)<>1 OR topic IS NULL OR kafka_partition IS NULL OR kafka_offset IS NULL UNION ALL SELECT topic,kafka_partition,kafka_offset FROM {{target:oil_stg__event_log}} WHERE event_json IS NULL OR received_at IS NULL OR batch_id IS NULL) q;
